1	"use client";
2	
3	import { useCallback, useEffect, useState } from "react";
4	import {
5	  getMailboxSettings,
6	  saveMailboxSettings,
7	  saveAutoReply,
8	  listAliases,
9	  addAlias,
10	  removeAlias,
11	  resetPassword,
12	  type MailboxSettings,
13	  type AliasRow,
14	} from "@/lib/actions-mailbox-settings";
15	import { Icon } from "./util";
16	
17	/** Mail server endpoints shown in the "configure your device" panel. */
18	const MAIL_HOST = "mail.nxeon.cloud";
19	
20	type Section = "identity" | "connection" | "aliases" | "autoreply" | "password";
21	
22	const SECTIONS: { key: Section; label: string; icon: keyof typeof Icon }[] = [
23	  { key: "identity", label: "Identity & signature", icon: "user" },
24	  { key: "connection", label: "Connection details", icon: "mail" },
25	  { key: "aliases", label: "Aliases", icon: "tag" },
26	  { key: "autoreply", label: "Auto-reply", icon: "reply" },
27	  { key: "password", label: "Change password", icon: "cog" },
28	];
29	
30	export function MailSettings({
31	  mailboxAddress,
32	  onClose,
33	  onSignatureSaved,
34	}: {
35	  mailboxAddress?: string;
36	  onClose: () => void;
37	  /** Notify the parent so a freshly-saved signature/display name applies immediately. */
38	  onSignatureSaved?: (s: { signature: string; displayName: string }) => void;
39	}) {
40	  const [section, setSection] = useState<Section>("identity");
41	  const [settings, setSettings] = useState<MailboxSettings | null>(null);
42	  const [loadError, setLoadError] = useState<string | null>(null);
43	
44	  useEffect(() => {
45	    let alive = true;
46	    setSettings(null);
47	    setLoadError(null);
48	    getMailboxSettings(mailboxAddress)
49	      .then((s) => alive && setSettings(s))
50	      .catch((e) => alive && setLoadError(e instanceof Error ? e.message : "Couldn't load settings."));
51	    return () => {
52	      alive = false;
53	    };
54	  }, [mailboxAddress]);
55	
56	  useEffect(() => {
57	    const onKey = (e: KeyboardEvent) => {
58	      if (e.key === "Escape") onClose();
59	    };
60	    window.addEventListener("keydown", onKey);
61	    return () => window.removeEventListener("keydown", onKey);
62	  }, [onClose]);
63	
64	  return (
65	    <div
66	      className="fixed inset-0 z-50 flex items-end justify-center bg-navy-950/70 p-0 backdrop-blur-sm sm:items-center sm:p-4"
67	      role="dialog"
68	      aria-modal="true"
69	      aria-label="Mailbox settings"
70	      onClick={onClose}
71	    >
72	      <div
73	        className="glass flex h-[88vh] w-full max-w-3xl flex-col overflow-hidden shadow-2xl animate-fade-up sm:h-[80vh]"
74	        onClick={(e) => e.stopPropagation()}
75	      >
76	        {/* Header */}
77	        <div className="flex items-center justify-between border-b border-white/[0.08] bg-white/[0.03] px-5 py-3">
78	          <div className="min-w-0">
79	            <h3 className="flex items-center gap-2 text-sm font-semibold text-white">
80	              <span className="text-brand-300"><Icon.cog size={16} /></span>
81	              Mailbox settings
82	            </h3>
83	            {settings && (
84	              <p className="mt-0.5 truncate text-xs text-slate-500" title={settings.address}>
85	                {settings.address}
86	              </p>
87	            )}
88	          </div>
89	          <button onClick={onClose} className="btn-ghost rounded-lg p-1.5" aria-label="Close">
90	            <Icon.close size={16} />
91	          </button>
92	        </div>
93	
94	        <div className="flex min-h-0 flex-1 flex-col sm:flex-row">
95	          {/* Section nav */}
96	          <nav className="flex flex-none gap-1 overflow-x-auto border-b border-white/[0.06] p-2 sm:w-52 sm:flex-col sm:overflow-x-visible sm:overflow-y-auto sm:border-b-0 sm:border-r">
97	            {SECTIONS.map((s) => {
98	              const Ico = Icon[s.icon];
99	              const active = section === s.key;
100	              return (
101	                <button
102	                  key={s.key}
103	                  onClick={() => setSection(s.key)}
104	                  className={`flex flex-none items-center gap-2.5 whitespace-nowrap rounded-xl px-3 py-2 text-sm font-medium transition-colors ${
105	                    active ? "nav-item-active" : "text-slate-400 hover:bg-white/[0.05] hover:text-white"
106	                  }`}
107	                >
108	                  <Ico size={16} className={active ? "text-white" : ""} />
109	                  <span className="hidden sm:inline">{s.label}</span>
110	                  <span className="sm:hidden">{s.label.split(" ")[0]}</span>
111	                </button>
112	              );
113	            })}
114	          </nav>
115	
116	          {/* Section content */}
117	          <div className="min-h-0 flex-1 overflow-y-auto p-5">
118	            {loadError ? (
119	              <ErrorNote text={loadError} />
120	            ) : !settings ? (
121	              <LoadingRows />
122	            ) : section === "identity" ? (
123	              <IdentitySection
124	                mailboxAddress={mailboxAddress}
125	                initial={settings}
126	                onSaved={(displayName, signature) => {
127	                  setSettings((cur) => (cur ? { ...cur, displayName, signature } : cur));
128	                  onSignatureSaved?.({ displayName, signature });
129	                }}
130	              />
131	            ) : section === "connection" ? (
132	              <ConnectionSection address={settings.address} />
133	            ) : section === "aliases" ? (
134	              <AliasesSection mailboxAddress={mailboxAddress} domain={settings.domain} />
135	            ) : section === "autoreply" ? (
136	              <AutoReplySection
137	                mailboxAddress={mailboxAddress}
138	                initial={settings}
139	                onSaved={(v) => setSettings((cur) => (cur ? { ...cur, ...v } : cur))}
140	              />
141	            ) : (
142	              <PasswordSection mailboxAddress={mailboxAddress} />
143	            )}
144	          </div>
145	        </div>
146	      </div>
147	    </div>
148	  );
149	}
150	
151	/* -------------------------------------------------------------------------- */
152	/* Section: Identity & signature                                               */
153	/* -------------------------------------------------------------------------- */
154	
155	function IdentitySection({
156	  mailboxAddress,
157	  initial,
158	  onSaved,
159	}: {
160	  mailboxAddress?: string;
161	  initial: MailboxSettings;
162	  onSaved: (displayName: string, signature: string) => void;
163	}) {
164	  const [displayName, setDisplayName] = useState(initial.displayName);
165	  const [signature, setSignature] = useState(initial.signature);
166	  const [saving, setSaving] = useState(false);
167	  const [msg, setMsg] = useState<string | null>(null);
168	  const [err, setErr] = useState<string | null>(null);
169	
170	  async function save() {
171	    setSaving(true);
172	    setMsg(null);
173	    setErr(null);
174	    try {
175	      const res = await saveMailboxSettings({ displayName, signature }, mailboxAddress);
176	      if (!res.ok) setErr(res.error || "Couldn't save.");
177	      else {
178	        setMsg("Saved.");
179	        onSaved(displayName.trim(), signature);
180	      }
181	    } catch (e) {
182	      setErr(e instanceof Error ? e.message : "Couldn't save.");
183	    } finally {
184	      setSaving(false);
185	    }
186	  }
187	
188	  return (
189	    <div className="space-y-5">
190	      <SectionHead
191	        title="Identity & signature"
192	        sub="Your name and signature appear on messages you send from this mailbox."
193	      />
194	      <div>
195	        <label className="label" htmlFor="ms-name">Display name</label>
196	        <input
197	          id="ms-name"
198	          className="input"
199	          value={displayName}
200	          onChange={(e) => setDisplayName(e.target.value)}
201	          placeholder="e.g. Jane Doe"
202	          maxLength={120}
203	        />
204	      </div>
205	      <div>
206	        <label className="label" htmlFor="ms-sig">Signature</label>
207	        <textarea
208	          id="ms-sig"
209	          className="input min-h-[9rem] resize-y font-mono leading-relaxed"
210	          value={signature}
211	          onChange={(e) => setSignature(e.target.value)}
212	          placeholder={"— \nJane Doe\nAcme Inc."}
213	          maxLength={5000}
214	        />
215	        <p className="mt-1.5 text-xs text-slate-500">
216	          Added below a separator on new messages, and beneath the quoted text on replies.
217	        </p>
218	      </div>
219	      <SaveRow saving={saving} msg={msg} err={err} onSave={save} />
220	    </div>
221	  );
222	}
223	
224	/* -------------------------------------------------------------------------- */
225	/* Section: Connection details                                                 */
226	/* -------------------------------------------------------------------------- */
227	
228	function ConnectionSection({ address }: { address: string }) {
229	  return (
230	    <div className="space-y-5">
231	      <SectionHead
232	        title="Connection details"
233	        sub="Use these to set up this mailbox in Outlook, Apple Mail, Thunderbird or any other mail app."
234	      />
235	
236	      <div className="space-y-3">
237	        <p className="section-label">Incoming — IMAP</p>
238	        <div className="grid gap-2 sm:grid-cols-2">
239	          <CopyField label="Server" value={MAIL_HOST} />
240	          <CopyField label="Port" value="993" />
241	          <CopyField label="Security" value="SSL / TLS" copyable={false} />
242	          <CopyField label="Username" value={address} />
243	        </div>
244	      </div>
245	
246	      <div className="space-y-3">
247	        <p className="section-label">Outgoing — SMTP</p>
248	        <div className="grid gap-2 sm:grid-cols-2">
249	          <CopyField label="Server" value={MAIL_HOST} />
250	          <CopyField label="Port" value="587" />
251	          <CopyField label="Security" value="STARTTLS" copyable={false} />
252	          <CopyField label="Username" value={address} />
253	        </div>
254	      </div>
255	
256	      <div className="rounded-xl border border-white/[0.08] bg-white/[0.02] px-4 py-3 text-xs text-slate-400">
257	        <span className="font-medium text-slate-300">Password:</span> use your mailbox password. If you
258	        don't have it, set a new one under <span className="text-slate-300">Change password</span>.
259	      </div>
260	    </div>
261	  );
262	}
263	
264	/* -------------------------------------------------------------------------- */
265	/* Section: Aliases                                                            */
266	/* -------------------------------------------------------------------------- */
267	
268	function AliasesSection({ mailboxAddress, domain }: { mailboxAddress?: string; domain: string }) {
269	  const [aliases, setAliases] = useState<AliasRow[] | null>(null);
270	  const [loadErr, setLoadErr] = useState<string | null>(null);
271	  const [newAlias, setNewAlias] = useState("");
272	  const [busy, setBusy] = useState(false);
273	  const [err, setErr] = useState<string | null>(null);
274	
275	  const load = useCallback(async () => {
276	    setLoadErr(null);
277	    try {
278	      const res = await listAliases(mailboxAddress);
279	      if (!res.ok) {
280	        setLoadErr(res.error || "Couldn't load aliases.");
281	        setAliases([]);
282	      } else {
283	        setAliases(res.aliases);
284	      }
285	    } catch (e) {
286	      setLoadErr(e instanceof Error ? e.message : "Couldn't load aliases.");
287	      setAliases([]);
288	    }
289	  }, [mailboxAddress]);
290	
291	  useEffect(() => {
292	    void load();
293	  }, [load]);
294	
295	  async function add() {
296	    const val = newAlias.trim();
297	    if (!val) return;
298	    setBusy(true);
299	    setErr(null);
300	    try {
301	      const res = await addAlias(val, undefined, mailboxAddress);
302	      if (!res.ok) setErr(res.error || "Couldn't add alias.");
303	      else {
304	        setNewAlias("");
305	        await load();
306	      }
307	    } catch (e) {
308	      setErr(e instanceof Error ? e.message : "Couldn't add alias.");
309	    } finally {
310	      setBusy(false);
311	    }
312	  }
313	
314	  async function remove(id: number) {
315	    setErr(null);
316	    // Optimistic removal.
317	    setAliases((cur) => (cur ? cur.filter((a) => a.id !== id) : cur));
318	    try {
319	      const res = await removeAlias(id, mailboxAddress);
320	      if (!res.ok) {
321	        setErr(res.error || "Couldn't remove alias.");
322	        await load();
323	      }
324	    } catch (e) {
325	      setErr(e instanceof Error ? e.message : "Couldn't remove alias.");
326	      await load();
327	    }
328	  }
329	
330	  return (
331	    <div className="space-y-5">
332	      <SectionHead
333	        title="Aliases"
334	        sub={`Extra addresses on ${domain || "your domain"} that deliver to this mailbox.`}
335	      />
336	
337	      {/* Add form */}
338	      <div className="flex flex-col gap-2 sm:flex-row">
339	        <div className="flex flex-1 items-stretch overflow-hidden rounded-xl border border-white/10 bg-navy-900/80 focus-within:border-brand-400/60 focus-within:ring-2 focus-within:ring-brand-500/20">
340	          <input
341	            className="min-w-0 flex-1 bg-transparent px-3.5 py-2.5 text-sm text-slate-100 outline-none placeholder:text-slate-500"
342	            value={newAlias}
343	            onChange={(e) => setNewAlias(e.target.value)}
344	            onKeyDown={(e) => {
345	              if (e.key === "Enter") void add();
346	            }}
347	            placeholder="sales"
348	            aria-label="New alias"
349	          />
350	          {!newAlias.includes("@") && domain && (
351	            <span className="flex flex-none items-center pr-3 text-sm text-slate-500">@{domain}</span>
352	          )}
353	        </div>
354	        <button className="btn-primary flex-none" onClick={add} disabled={busy || !newAlias.trim()}>
355	          {busy ? "Adding…" : "Add alias"}
356	        </button>
357	      </div>
358	      {err && <ErrorNote text={err} />}
359	
360	      {/* List */}
361	      {aliases === null ? (
362	        <LoadingRows rows={3} />
363	      ) : loadErr ? (
364	        <ErrorNote text={loadErr} />
365	      ) : aliases.length === 0 ? (
366	        <EmptyNote text="No aliases yet. Add one above to start forwarding another address into this mailbox." />
367	      ) : (
368	        <ul className="divide-y divide-white/[0.06] overflow-hidden rounded-xl border border-white/[0.06]">
369	          {aliases.map((a) => (
370	            <li key={a.id} className="flex items-center gap-3 px-4 py-2.5">
371	              <span className="text-brand-300"><Icon.tag size={15} /></span>
372	              <div className="min-w-0 flex-1">
373	                <p className="truncate font-mono text-sm text-slate-100">{a.address}</p>
374	                <p className="truncate text-xs text-slate-500">→ {a.goto || "—"}</p>
375	              </div>
376	              {!a.active && <span className="flex-none text-[11px] text-amber-300">inactive</span>}
377	              <button
378	                onClick={() => remove(a.id)}
379	                className="btn-ghost flex-none rounded-lg p-1.5 text-slate-500 hover:text-red-300"
380	                aria-label={`Remove alias ${a.address}`}
381	                title="Remove alias"
382	              >
383	                <Icon.trash size={15} />
384	              </button>
385	            </li>
386	          ))}
387	        </ul>
388	      )}
389	    </div>
390	  );
391	}
392	
393	/* -------------------------------------------------------------------------- */
394	/* Section: Auto-reply                                                         */
395	/* -------------------------------------------------------------------------- */
396	
397	function AutoReplySection({
398	  mailboxAddress,
399	  initial,
400	  onSaved,
401	}: {
402	  mailboxAddress?: string;
403	  initial: MailboxSettings;
404	  onSaved: (v: { autoReplyEnabled: boolean; autoReplySubject: string; autoReplyBody: string }) => void;
405	}) {
406	  const [enabled, setEnabled] = useState(initial.autoReplyEnabled);
407	  const [subject, setSubject] = useState(initial.autoReplySubject);
408	  const [body, setBody] = useState(initial.autoReplyBody);
409	  const [saving, setSaving] = useState(false);
410	  const [msg, setMsg] = useState<string | null>(null);
411	  const [err, setErr] = useState<string | null>(null);
412	
413	  async function save() {
414	    setSaving(true);
415	    setMsg(null);
416	    setErr(null);
417	    try {
418	      const res = await saveAutoReply({ enabled, subject, body }, mailboxAddress);
419	      if (!res.ok) setErr(res.error || "Couldn't save.");
420	      else {
421	        setMsg("Saved.");
422	        onSaved({ autoReplyEnabled: enabled, autoReplySubject: subject.trim(), autoReplyBody: body.trim() });
423	      }
424	    } catch (e) {
425	      setErr(e instanceof Error ? e.message : "Couldn't save.");
426	    } finally {
427	      setSaving(false);
428	    }
429	  }
430	
431	  return (
432	    <div className="space-y-5">
433	      <SectionHead
434	        title="Auto-reply"
435	        sub="Send an automatic response to incoming messages while you're away."
436	      />
437	
438	      <button
439	        type="button"
440	        onClick={() => setEnabled((v) => !v)}
441	        className="flex w-full items-center justify-between rounded-xl border border-white/[0.08] bg-white/[0.02] px-4 py-3 text-left transition-colors hover:border-white/20"
442	      >
443	        <span className="text-sm font-medium text-slate-200">Auto-reply {enabled ? "on" : "off"}</span>
444	        <span
445	          className={`relative h-6 w-11 flex-none rounded-full transition-colors ${enabled ? "bg-brand-500" : "bg-white/10"}`}
446	        >
447	          <span
448	            className={`absolute top-0.5 h-5 w-5 rounded-full bg-white shadow transition-transform ${enabled ? "translate-x-[22px]" : "translate-x-0.5"}`}
449	          />
450	        </span>
451	      </button>
452	
453	      <div className={enabled ? "space-y-4" : "space-y-4 opacity-50"}>
454	        <div>
455	          <label className="label" htmlFor="ar-subject">Subject</label>
456	          <input
457	            id="ar-subject"
458	            className="input"
459	            value={subject}
460	            onChange={(e) => setSubject(e.target.value)}
461	            placeholder="Out of office"
462	            maxLength={200}
463	            disabled={!enabled}
464	          />
465	        </div>
466	        <div>
467	          <label className="label" htmlFor="ar-body">Message</label>
468	          <textarea
469	            id="ar-body"
470	            className="input min-h-[8rem] resize-y leading-relaxed"
471	            value={body}
472	            onChange={(e) => setBody(e.target.value)}
473	            placeholder="Thanks for your email. I'm away until…"
474	            maxLength={5000}
475	            disabled={!enabled}
476	          />
477	        </div>
478	      </div>
479	
480	      <div className="rounded-xl border border-amber-400/20 bg-amber-400/[0.06] px-4 py-3 text-xs text-amber-200/90">
481	        Auto-reply is saved to your mailbox. Server-side delivery of auto-replies is rolling out — until
482	        then, these settings are stored but not yet sent automatically.
483	      </div>
484	
485	      <SaveRow saving={saving} msg={msg} err={err} onSave={save} />
486	    </div>
487	  );
488	}
489	
490	/* -------------------------------------------------------------------------- */
491	/* Section: Change password                                                    */
492	/* -------------------------------------------------------------------------- */
493	
494	function PasswordSection({ mailboxAddress }: { mailboxAddress?: string }) {
495	  const [busy, setBusy] = useState(false);
496	  const [password, setPassword] = useState<string | null>(null);
497	  const [err, setErr] = useState<string | null>(null);
498	
499	  async function reset() {
500	    if (!confirm("Reset this mailbox's password? The current password will stop working everywhere.")) return;
501	    setBusy(true);
502	    setErr(null);
503	    setPassword(null);
504	    try {
505	      const res = await resetPassword(mailboxAddress);
506	      if (res.error) setErr(res.error);
507	      else if (res.password) setPassword(res.password);
508	    } catch (e) {
509	      setErr(e instanceof Error ? e.message : "Couldn't reset the password.");
510	    } finally {
511	      setBusy(false);
512	    }
513	  }
514	
515	  return (
516	    <div className="space-y-5">
517	      <SectionHead
518	        title="Change password"
519	        sub="Generate a new password for this mailbox. It applies to webmail and any connected mail apps."
520	      />
521	
522	      {password ? (
523	        <div className="space-y-3">
524	          <div className="rounded-xl border border-emerald-400/20 bg-emerald-400/[0.06] px-4 py-3 text-xs text-emerald-200/90">
525	            New password set. Copy it now — it won't be shown again.
526	          </div>
527	          <CopyField label="New password" value={password} mono />
528	        </div>
529	      ) : (
530	        <p className="text-sm text-slate-400">
531	          A strong password is generated and applied on the mail server, then shown once here for you to
532	          copy into your other mail apps.
533	        </p>
534	      )}
535	
536	      {err && <ErrorNote text={err} />}
537	
538	      <button className="btn-secondary" onClick={reset} disabled={busy}>
539	        {busy ? "Resetting…" : password ? "Reset again" : "Reset password"}
540	      </button>
541	    </div>
542	  );
543	}
544	
545	/* -------------------------------------------------------------------------- */
546	/* Small shared pieces                                                         */
547	/* -------------------------------------------------------------------------- */
548	
549	function SectionHead({ title, sub }: { title: string; sub: string }) {
550	  return (
551	    <div>
552	      <h4 className="text-base font-semibold text-white">{title}</h4>
553	      <p className="mt-1 text-sm text-slate-400">{sub}</p>
554	    </div>
555	  );
556	}
557	
558	function SaveRow({
559	  saving,
560	  msg,
561	  err,
562	  onSave,
563	}: {
564	  saving: boolean;
565	  msg: string | null;
566	  err: string | null;
567	  onSave: () => void;
568	}) {
569	  return (
570	    <div className="flex items-center gap-3 pt-1">
571	      <button className="btn-primary" onClick={onSave} disabled={saving}>
572	        {saving ? "Saving…" : "Save changes"}
573	      </button>
574	      {msg && <span className="text-xs text-emerald-300">{msg}</span>}
575	      {err && <span className="text-xs text-red-300">{err}</span>}
576	    </div>
577	  );
578	}
579	
580	function CopyField({
581	  label,
582	  value,
583	  copyable = true,
584	  mono = false,
585	}: {
586	  label: string;
587	  value: string;
588	  copyable?: boolean;
589	  mono?: boolean;
590	}) {
591	  const [copied, setCopied] = useState(false);
592	  const copy = useCallback(async () => {
593	    try {
594	      await navigator.clipboard.writeText(value);
595	      setCopied(true);
596	      setTimeout(() => setCopied(false), 1400);
597	    } catch {
598	      /* clipboard blocked — no-op */
599	    }
600	  }, [value]);
601	
602	  return (
603	    <div className="flex items-center gap-2 rounded-xl border border-white/[0.08] bg-navy-900/60 px-3 py-2">
604	      <div className="min-w-0 flex-1">
605	        <p className="text-[10px] font-semibold uppercase tracking-wide text-slate-500">{label}</p>
606	        <p className={`truncate text-sm text-slate-100 ${mono ? "font-mono" : ""}`} title={value}>
607	          {value}
