3	// Server actions for the native webmail "Mailbox settings" panel
4	// (components/customer/mail/MailSettings.tsx, opened from the FolderRail).
5	//
6	// Every action authenticates the caller and resolves ONLY a mailbox they own via
7	// `resolveMailbox` (which also performs the ownership check used everywhere else
8	// in the mail client). Writes are rate-limited and return a friendly
9	// `{ ok, error }`. Alias operations additionally verify the target domain is one
10	// the caller actually owns (an EmailSubscription) before touching Mailcow.
11	
12	import { db } from "@/lib/db";
13	import { checkRateLimit } from "@/lib/rate-limit";
14	import { resolveMailbox } from "@/lib/mail/imap";
15	import {
16	  mailcowConfigured,
17	  mcListAliases,
18	  mcAddAlias,
19	  mcDeleteAlias,
20	  type MailcowAlias,
21	} from "@/lib/mailcow";
22	import { resetMailboxPassword } from "@/lib/actions-email-hosting";
23	
24	export type Result = { ok: boolean; error?: string };
25	
26	const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
27	
28	/** Serialisable mailbox settings the panel reads/writes. */
29	export type MailboxSettings = {
30	  address: string;
31	  domain: string;
32	  displayName: string;
33	  signature: string;
34	  autoReplyEnabled: boolean;
35	  autoReplySubject: string;
36	  autoReplyBody: string;
37	};
38	
39	function domainOf(address: string): string {
40	  const at = address.lastIndexOf("@");
41	  return at >= 0 ? address.slice(at + 1).toLowerCase() : "";
42	}
43	
44	/** Rate-limit gate returning a friendly `{ ok:false }` instead of throwing. */
45	function gate(key: string, max: number, windowMs: number): Result | null {
46	  const r = checkRateLimit(key, { max, windowMs });
47	  if (!r.ok) return { ok: false, error: `Too many requests — wait ${r.retryAfterSec}s and try again.` };
48	  return null;
49	}
50	
51	/** The domains the signed-in user owns (from their email subscriptions). */
52	async function ownedDomains(userId: string): Promise<Set<string>> {
53	  const subs = await db.emailSubscription.findMany({
54	    where: { userId },
55	    select: { domainName: true },
56	  });
57	  return new Set(subs.map((s) => s.domainName.trim().toLowerCase()).filter(Boolean));
58	}
59	
60	// ---------------------------------------------------------------------------
61	// Identity, signature, auto-reply (stored on the Mailbox row)
62	// ---------------------------------------------------------------------------
63	
64	/** Load the current settings for a mailbox the caller owns. */
65	export async function getMailboxSettings(mailboxAddress?: string): Promise<MailboxSettings> {
66	  const { mailboxId, address } = await resolveMailbox(mailboxAddress);
67	  const row = await db.mailbox.findUnique({ where: { id: mailboxId } });
68	  return {
69	    address,
70	    domain: domainOf(address),
71	    displayName: row?.displayName ?? "",
72	    signature: row?.signature ?? "",
73	    autoReplyEnabled: row?.autoReplyEnabled ?? false,
74	    autoReplySubject: row?.autoReplySubject ?? "",
75	    autoReplyBody: row?.autoReplyBody ?? "",
76	  };
77	}
78	
79	/** Save the display name + signature onto the mailbox row. */
80	export async function saveMailboxSettings(
81	  input: { displayName?: string; signature?: string },
82	  mailboxAddress?: string,
83	): Promise<Result> {
84	  const { user, mailboxId } = await resolveMailbox(mailboxAddress);
85	  const limited = gate(`mail:settings:${user.id}`, 30, 60_000);
86	  if (limited) return limited;
87	
88	  const displayName = (input.displayName ?? "").trim();
89	  const signature = input.signature ?? "";
90	  if (displayName.length > 120) return { ok: false, error: "Display name is too long (max 120 characters)." };
91	  if (signature.length > 5000) return { ok: false, error: "Signature is too long (max 5000 characters)." };
92	
93	  await db.mailbox.update({
94	    where: { id: mailboxId },
95	    data: { displayName: displayName || null, signature: signature.trim() ? signature : null },
96	  });
97	  return { ok: true };
98	}
99	
100	/**
101	 * Save the auto-reply / vacation responder onto the mailbox row.
102	 *
103	 * NOTE: this is STORE-ONLY. Mailcow's REST API exposes no reliable
104	 * vacation/auto-responder endpoint (auto-replies live in SOGo user preferences,
105	 * not the admin API), so we persist the settings and the UI labels them as
106	 * "saved; server-side delivery is rolling out". We do NOT pretend the mail
107	 * server sends them.
108	 */
109	export async function saveAutoReply(
110	  input: { enabled: boolean; subject?: string; body?: string },
111	  mailboxAddress?: string,
112	): Promise<Result> {
113	  const { user, mailboxId } = await resolveMailbox(mailboxAddress);
114	  const limited = gate(`mail:settings:${user.id}`, 30, 60_000);
115	  if (limited) return limited;
116	
117	  const enabled = Boolean(input.enabled);
118	  const subject = (input.subject ?? "").trim();
119	  const body = (input.body ?? "").trim();
120	  if (subject.length > 200) return { ok: false, error: "Subject is too long (max 200 characters)." };
121	  if (body.length > 5000) return { ok: false, error: "Message is too long (max 5000 characters)." };
122	  if (enabled && !body) return { ok: false, error: "Add an auto-reply message before turning it on." };
123	
124	  await db.mailbox.update({
125	    where: { id: mailboxId },
126	    data: {
127	      autoReplyEnabled: enabled,
128	      autoReplySubject: subject || null,
129	      autoReplyBody: body || null,
130	    },
131	  });
132	  return { ok: true };
133	}
134	
135	// ---------------------------------------------------------------------------
136	// Aliases (Mailcow)
137	// ---------------------------------------------------------------------------
138	
139	export type AliasRow = { id: number; address: string; goto: string; active: boolean };
140	
141	function toAliasRows(list: MailcowAlias[]): AliasRow[] {
142	  return list.map((a) => ({ id: a.id, address: a.address, goto: a.goto, active: a.active }));
143	}
144	
145	/** List the aliases on the mailbox's domain. */
146	export async function listAliases(
147	  mailboxAddress?: string,
148	): Promise<{ ok: boolean; error?: string; aliases: AliasRow[] }> {
149	  const { user, address } = await resolveMailbox(mailboxAddress);
150	  const domain = domainOf(address);
151	  if (!mailcowConfigured()) return { ok: false, error: "Mail server is not configured yet.", aliases: [] };
152	
153	  const owned = await ownedDomains(user.id);
154	  if (!owned.has(domain)) return { ok: false, error: "You don't own this mailbox's domain.", aliases: [] };
155	
156	  try {
157	    const list = await mcListAliases(domain);
158	    return { ok: true, aliases: toAliasRows(list) };
159	  } catch (e) {
160	    return { ok: false, error: friendly(e), aliases: [] };
161	  }
162	}
163	
164	/**
165	 * Add an alias on a domain the caller owns. `alias` may be a full address or a
166	 * bare local part (the mailbox's own domain is assumed). `goto` defaults to the
167	 * mailbox itself.
168	 */
169	export async function addAlias(alias: string, goto?: string, mailboxAddress?: string): Promise<Result> {
170	  const { user, address } = await resolveMailbox(mailboxAddress);
171	  const limited = gate(`mail:alias:${user.id}`, 20, 60_000);
172	  if (limited) return limited;
173	  if (!mailcowConfigured()) return { ok: false, error: "Mail server is not configured yet." };
174	
175	  let aliasAddr = (alias ?? "").trim().toLowerCase();
176	  if (!aliasAddr) return { ok: false, error: "Enter an alias address." };
177	  // Accept a bare local part — assume the mailbox's own domain.
178	  if (!aliasAddr.includes("@")) aliasAddr = `${aliasAddr}@${domainOf(address)}`;
179	  if (!EMAIL_RE.test(aliasAddr)) return { ok: false, error: "That doesn't look like a valid email address." };
180	
181	  const owned = await ownedDomains(user.id);
182	  if (!owned.has(domainOf(aliasAddr))) {
183	    return { ok: false, error: "You can only add aliases on a domain you own." };
184	  }
185	
186	  const dest = (goto ?? "").trim() || address;
187	  if (!EMAIL_RE.test(dest)) return { ok: false, error: "The destination address is not valid." };
188	  if (dest.toLowerCase() === aliasAddr) return { ok: false, error: "An alias can't point to itself." };
189	
190	  try {
191	    await mcAddAlias(aliasAddr, dest);
192	    return { ok: true };
193	  } catch (e) {
194	    return { ok: false, error: friendly(e) };
195	  }
196	}
197	
198	/** Remove an alias by id, after verifying it lives on a domain the caller owns. */
199	export async function removeAlias(id: number, mailboxAddress?: string): Promise<Result> {
200	  const { user, address } = await resolveMailbox(mailboxAddress);
201	  const limited = gate(`mail:alias:${user.id}`, 20, 60_000);
202	  if (limited) return limited;
203	  if (!mailcowConfigured()) return { ok: false, error: "Mail server is not configured yet." };
204	  if (!Number.isFinite(id)) return { ok: false, error: "Invalid alias." };
205	
206	  const domain = domainOf(address);
207	  const owned = await ownedDomains(user.id);
208	  if (!owned.has(domain)) return { ok: false, error: "You don't own this mailbox's domain." };
209	
210	  try {
211	    // Confirm the alias belongs to this owned domain before deleting.
212	    const list = await mcListAliases(domain);
213	    const match = list.find((a) => a.id === id);
214	    if (!match) return { ok: false, error: "That alias no longer exists on your domain." };
215	    await mcDeleteAlias(id);
216	    return { ok: true };
217	  } catch (e) {
218	    return { ok: false, error: friendly(e) };
219	  }
220	}
221	
222	// ---------------------------------------------------------------------------
223	// Change password (reuses the owner-checked, rate-limited hosting action)
224	// ---------------------------------------------------------------------------
225	
226	/** Reset the mailbox password; returns the new password once for the customer. */
227	export async function resetPassword(
228	  mailboxAddress?: string,
229	): Promise<{ error?: string; password?: string }> {
230	  const { mailboxId } = await resolveMailbox(mailboxAddress);
231	  return resetMailboxPassword(mailboxId);
232	}
233	
234	/** Turn a thrown error into a short, safe message for the UI. */
235	function friendly(e: unknown): string {
236	  const msg = e instanceof Error ? e.message : String(e);
237	  return msg.replace(/\s+/g, " ").slice(0, 200) || "Something went wrong. Please try again.";
238	}
