19	export function Composer({
20	  draft,
21	  onClose,
22	  onSend,
23	}: {
24	  draft: ComposeDraft;
25	  onClose: () => void;
26	  onSend: (payload: SendPayload) => Promise<void>;
27	}) {
28	  const [to, setTo] = useState(draft.to);
29	  const [cc, setCc] = useState(draft.cc);
30	  const [showCc, setShowCc] = useState(!!draft.cc);
31	  const [subject, setSubject] = useState(draft.subject);
32	  const [body, setBody] = useState(draft.body);
33	  const [sending, setSending] = useState(false);
34	  const [error, setError] = useState<string | null>(null);
35	
36	  useEffect(() => {
37	    const onKey = (e: KeyboardEvent) => {
38	      if (e.key === "Escape" && !sending) onClose();
39	      if ((e.metaKey || e.ctrlKey) && e.key === "Enter") void submit();
40	    };
41	    window.addEventListener("keydown", onKey);
42	    return () => window.removeEventListener("keydown", onKey);
43	    // eslint-disable-next-line react-hooks/exhaustive-deps
44	  }, [to, cc, subject, body, sending]);
45	
46	  const title =
47	    draft.mode === "new" ? "New message" : draft.mode === "forward" ? "Forward" : "Reply";
48	
49	  async function submit() {
50	    if (sending) return;
51	    if (!to.trim()) {
52	      setError("Add at least one recipient.");
53	      return;
54	    }
55	    setError(null);
56	    setSending(true);
57	    try {
58	      const esc = (s: string) => s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
59	      // Compose the outgoing body. User text becomes both the text part and,
60	      // combined with any quoted original, a simple HTML part.
61	      const escaped = esc(body);
62	      // For replies/forwards the signature is appended BELOW the quoted original
63	      // (plain text, treated as text for safety). New messages already carry the
64	      // signature inline in `body`, so no separate block is added there.
65	      const sig = draft.signature?.trim();
66	      const sigText = sig ? `\n\n-- \n${sig}` : "";
67	      const sigHtml = sig
68	        ? `<br><div style="white-space:pre-wrap;font-family:-apple-system,Segoe UI,Roboto,sans-serif;font-size:13px;line-height:1.6;color:#64748b">-- <br>${esc(sig)}</div>`
69	        : "";
