71	        `<div style="white-space:pre-wrap;font-family:-apple-system,Segoe UI,Roboto,sans-serif;font-size:14px;line-height:1.6;color:#1e293b">${escaped}</div>` +
72	        (draft.quotedHtml
73	          ? `<br><blockquote style="margin:0 0 0 12px;padding-left:12px;border-left:3px solid #e2e8f0;color:#64748b">${draft.quotedHtml}</blockquote>`
74	          : "") +
75	        sigHtml;
76	
77	      await onSend({
78	        to: to.trim(),
79	        cc: cc.trim() || undefined,
80	        subject: subject.trim() || "(no subject)",
81	        text: body + sigText,
82	        html: htmlBody,
83	        inReplyToUid: draft.inReplyToUid,
84	        replyFolder: draft.replyFolder,
