89	      setSending(false);
90	    }
91	  }
92	
93	  return (
94	    <div className="fixed inset-0 z-50 flex items-end justify-center bg-navy-950/70 p-0 backdrop-blur-sm sm:items-center sm:p-4" role="dialog" aria-modal="true" aria-label={title}>
95	      <div
96	        className="glass flex h-[85vh] w-full max-w-2xl flex-col overflow-hidden shadow-2xl animate-fade-up sm:h-auto sm:max-h-[85vh]"
97	        onClick={(e) => e.stopPropagation()}
98	      >
99	        {/* Header */}
100	        <div className="flex items-center justify-between border-b border-white/[0.08] bg-white/[0.03] px-5 py-3">
101	          <h3 className="flex items-center gap-2 text-sm font-semibold text-white">
102	            <span className="text-brand-300"><Icon.compose size={16} /></span>
103	            {title}
104	          </h3>
105	          <button onClick={onClose} className="btn-ghost rounded-lg p-1.5" aria-label="Close">
106	            <Icon.close size={16} />
107	          </button>
108	        </div>
109	
110	        {/* Fields */}
111	        <div className="flex-1 overflow-y-auto">
112	          <FieldRow label="To">
113	            <input
114	              autoFocus={draft.mode !== "reply" && draft.mode !== "replyAll"}
115	              value={to}
116	              onChange={(e) => setTo(e.target.value)}
117	              placeholder="name@example.com, another@example.com"
118	              className="w-full bg-transparent text-sm text-slate-100 outline-none placeholder:text-slate-600"
119	            />
120	            {!showCc && (
121	              <button onClick={() => setShowCc(true)} className="ml-2 flex-none text-xs font-medium text-slate-500 hover:text-brand-300">
122	                Cc
123	              </button>
124	            )}
125	          </FieldRow>
126	
127	          {showCc && (
128	            <FieldRow label="Cc">
129	              <input
130	                value={cc}
131	                onChange={(e) => setCc(e.target.value)}
132	                placeholder="cc@example.com"
133	                className="w-full bg-transparent text-sm text-slate-100 outline-none placeholder:text-slate-600"
134	              />
135	            </FieldRow>
136	          )}
137	
138	          <FieldRow label="Subject">
139	            <input
140	              value={subject}
141	              onChange={(e) => setSubject(e.target.value)}
142	              placeholder="Subject"
143	              className="w-full bg-transparent text-sm text-slate-100 outline-none placeholder:text-slate-600"
144	            />
145	          </FieldRow>
146	
147	          <textarea
148	            autoFocus={draft.mode === "reply" || draft.mode === "replyAll"}
149	            value={body}
150	            onChange={(e) => setBody(e.target.value)}
151	            placeholder="Write your message…"
152	            className="min-h-[16rem] w-full flex-1 resize-none bg-transparent px-5 py-4 text-sm leading-relaxed text-slate-100 outline-none placeholder:text-slate-600"
153	          />
154	
155	          {draft.quotedHtml && (
156	            <p className="px-5 pb-4 text-xs text-slate-600">
157	              — the original message is quoted below your reply —
158	            </p>
159	          )}
160	        </div>
161	
162	        {/* Footer */}
163	        <div className="flex items-center justify-between gap-3 border-t border-white/[0.08] bg-white/[0.02] px-5 py-3">
164	          <div className="min-w-0 text-xs text-red-300">{error}</div>
165	          <div className="flex flex-none items-center gap-2">
166	            <span className="hidden text-[11px] text-slate-600 sm:inline">
167	              <span className="kbd">⌘/Ctrl</span> + <span className="kbd">Enter</span>
