1	// Mailcow REST API client.
2	//
3	// Plain server-side module (NO "use server") — safe to import from server
4	// actions, route handlers, server components and the worker; never bundled to
5	// the client. Talks to a self-hosted Mailcow instance over its REST API.
6	//
7	// Configuration is read from the environment at call time (never hardcoded):
8	//   MAILCOW_API_URL  e.g. https://mail.nxeon.cloud/api/v1
9	//   MAILCOW_API_KEY  the X-API-Key value
10	//
11	// Every function throws a clear Error on a non-success response (including when
12	// Mailcow itself replies with a `{type:"danger"|"error"}` payload) or when the
13	// integration is not configured. Callers that must stay failure-tolerant (the
14	// order flow) wrap these in try/catch.
15	
16	export class MailcowError extends Error {
17	  constructor(
18	    message: string,
19	    public status?: number,
20	    public body?: unknown,
21	  ) {
22	    super(message);
23	    this.name = "MailcowError";
24	  }
25	}
26	
27	/** Both env vars present and non-empty. */
28	export function mailcowConfigured(): boolean {
29	  return Boolean(
30	    process.env.MAILCOW_API_URL?.trim() && process.env.MAILCOW_API_KEY?.trim(),
31	  );
32	}
33	
34	function config(): { base: string; key: string } {
35	  const base = process.env.MAILCOW_API_URL?.trim();
36	  const key = process.env.MAILCOW_API_KEY?.trim();
37	  if (!base || !key) {
38	    throw new MailcowError(
39	      "Mailcow not configured — set MAILCOW_API_URL and MAILCOW_API_KEY.",
40	    );
41	  }
42	  return { base: base.replace(/\/+$/, ""), key };
43	}
44	
45	/**
46	 * Core request helper. Performs a fetch to `${MAILCOW_API_URL}${path}` with the
47	 * X-API-Key header, parses the JSON body, and throws a MailcowError on any
48	 * non-2xx status or on a Mailcow error payload.
49	 */
50	async function mcRequest(
51	  method: "GET" | "POST",
52	  path: string,
53	  body?: unknown,
54	): Promise<unknown> {
55	  const { base, key } = config();
56	  const url = `${base}${path.startsWith("/") ? path : `/${path}`}`;
57	
58	  let res: Response;
59	  try {
60	    res = await fetch(url, {
61	      method,
62	      headers: {
63	        "X-API-Key": key,
64	        "Content-Type": "application/json",
65	        Accept: "application/json",
66	      },
67	      body: body === undefined ? undefined : JSON.stringify(body),
68	      cache: "no-store",
69	    });
70	  } catch (e) {
71	    throw new MailcowError(
72	      `Mailcow unreachable (${method} ${path}): ${e instanceof Error ? e.message : String(e)}`,
73	    );
74	  }
75	
76	  const text = await res.text();
77	  let parsed: unknown = text;
78	  try {
79	    parsed = text ? JSON.parse(text) : null;
80	  } catch {
81	    // leave parsed as raw text
82	  }
83	
84	  if (!res.ok) {
85	    throw new MailcowError(
86	      `Mailcow ${method} ${path} -> HTTP ${res.status}`,
87	      res.status,
88	      parsed,
89	    );
90	  }
91	
92	  assertNoApiError(parsed, `${method} ${path}`);
93	  return parsed;
94	}
95	
96	/**
97	 * Mailcow POST endpoints return HTTP 200 even on logical failure, signalling the
98	 * outcome via `type` in the (array-wrapped) payload. Detect and surface those.
99	 */
100	function assertNoApiError(parsed: unknown, ctx: string): void {
101	  const entries = Array.isArray(parsed) ? parsed : [parsed];
102	  for (const entry of entries) {
103	    if (entry && typeof entry === "object" && "type" in entry) {
104	      const type = String((entry as { type: unknown }).type ?? "").toLowerCase();
105	      if (type === "danger" || type === "error") {
106	        const rawMsg = (entry as { msg?: unknown }).msg;
107	        const msg = Array.isArray(rawMsg) ? rawMsg.join(" ") : String(rawMsg ?? "unknown error");
108	        throw new MailcowError(`Mailcow ${ctx} failed: ${msg}`, undefined, parsed);
109	      }
110	    }
111	  }
112	}
