114	// ---------- Mutations ----------
115	
116	/** Create a mail domain (idempotent-ish: if it already exists Mailcow errors,
117	 * which callers may ignore). */
118	export async function mcCreateDomain(domain: string): Promise<unknown> {
119	  return mcRequest("POST", "/add/domain", {
120	    domain,
121	    description: `nxeon ${domain}`,
122	    aliases: 400,
123	    mailboxes: 100,
124	    defquota: 1024,
125	    maxquota: 102400,
126	    quota: 102400,
127	    active: "1",
