132	/** True if the domain already exists in Mailcow. */
133	export async function mcDomainExists(domain: string): Promise<boolean> {
134	  try {
135	    const res = await mcRequest("GET", `/get/domain/${encodeURIComponent(domain)}`);
136	    // Mailcow returns {} (or []) for an unknown domain, or the domain object.
137	    if (!res) return false;
138	    if (Array.isArray(res)) return res.length > 0;
139	    if (typeof res === "object") {
140	      return "domain_name" in res || "domain" in res;
141	    }
142	    return false;
143	  } catch {
144	    return false;
145	  }
