// Signature helpers shared by the client (editor + preview) and the server
// (actions that persist / derive the plain-text part). Plain module — NO
// "use server" — so it can be imported from both React client components and
// server actions. Pure string helpers, no side effects.
//
// All rich-signature HTML must additionally be run through `safeHtml`
// (lib/mail/render.ts) before it is stored, previewed or sent. This module only
// derives a plain-text fallback and provides UI constants/templates.

export type SignaturePlacement = "above" | "below";

/** Max length of the (sanitized) signature HTML we accept. */
export const SIGNATURE_HTML_MAX = 20000;

/** Font families offered in the editor toolbar (label + CSS stack). */
export const SIGNATURE_FONTS: { label: string; css: string }[] = [
  { label: "Default (sans-serif)", css: "-apple-system, Segoe UI, Roboto, Helvetica, Arial, sans-serif" },
  { label: "Serif", css: "Georgia, 'Times New Roman', serif" },
  { label: "Monospace", css: "'SFMono-Regular', Consolas, 'Liberation Mono', monospace" },
  { label: "Arial", css: "Arial, Helvetica, sans-serif" },
  { label: "Georgia", css: "Georgia, serif" },
  { label: "Times New Roman", css: "'Times New Roman', Times, serif" },
];

/** Font sizes for the toolbar (execCommand fontSize takes 1..7). */
export const SIGNATURE_SIZES: { label: string; value: string }[] = [
  { label: "Small", value: "2" },
  { label: "Normal", value: "3" },
  { label: "Large", value: "5" },
  { label: "Huge", value: "6" },
];

const ENTITY_MAP: Record<string, string> = {
  "&nbsp;": " ",
  "&amp;": "&",
  "&lt;": "<",
  "&gt;": ">",
  "&quot;": '"',
  "&#39;": "'",
  "&apos;": "'",
  "&mdash;": "—",
  "&ndash;": "–",
  "&hellip;": "…",
};

/**
 * Derive a readable plain-text version of a (sanitized) HTML signature, for the
 * text/plain MIME part and as the legacy `signature` fallback. Turns block
 * boundaries and <br> into newlines, list items into "• ", <hr> into a rule,
 * strips remaining tags and decodes the common entities. Never throws.
 */
export function signatureHtmlToText(html: string | null | undefined): string {
  if (!html) return "";
  let t = String(html);
  t = t.replace(/<\s*br\s*\/?\s*>/gi, "\n");
  t = t.replace(/<\s*hr[^>]*>/gi, "\n----------\n");
  t = t.replace(/<\s*li[^>]*>/gi, "• ");
  t = t.replace(/<\/\s*(p|div|li|h[1-6]|tr|ul|ol)\s*>/gi, "\n");
  t = t.replace(/<[^>]+>/g, "");
  t = t.replace(/&(?:nbsp|amp|lt|gt|quot|#39|apos|mdash|ndash|hellip);/gi, (m) => ENTITY_MAP[m.toLowerCase()] ?? ENTITY_MAP[m] ?? m);
  t = t.replace(/&#x([0-9a-f]+);/gi, (_, h) => codePoint(parseInt(h, 16)));
  t = t.replace(/&#(\d+);/g, (_, d) => codePoint(parseInt(d, 10)));
  // Tidy whitespace.
  t = t.replace(/\r/g, "");
  t = t.replace(/[ \t]+\n/g, "\n");
  t = t.replace(/\n{3,}/g, "\n\n");
  return t.trim();
}

function codePoint(n: number): string {
  if (!Number.isFinite(n) || n < 0 || n > 0x10ffff) return "";
  try {
    return String.fromCodePoint(n);
  } catch {
    return "";
  }
}

/** Escape user text for safe interpolation into signature HTML templates. */
function esc(s: string): string {
  return s
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;");
}

/**
 * Starter signature templates the user can insert. `name`/`org` seed the block
 * from the mailbox identity so the result is immediately usable and editable.
 */
export function signatureTemplates(opts: { name?: string; org?: string; email?: string }): {
  id: string;
  label: string;
  html: string;
}[] {
  const name = esc((opts.name || "Your Name").trim());
  const org = esc((opts.org || "Company").trim());
  const email = esc((opts.email || "you@example.com").trim());
  const brand = "#6f47f5";
  return [
    {
      id: "classic",
      label: "Classic",
      html:
        `<div style="font-family:-apple-system,Segoe UI,Roboto,sans-serif;font-size:13px;line-height:1.5;color:#334155">` +
        `<div style="font-weight:600;color:#0f172a">${name}</div>` +
        `<div style="color:#64748b">Title • ${org}</div>` +
        `<div style="color:#64748b">${email}</div>` +
        `</div>`,
    },
    {
      id: "accent",
      label: "Accent bar",
      html:
        `<table cellpadding="0" cellspacing="0" style="font-family:-apple-system,Segoe UI,Roboto,sans-serif;font-size:13px;line-height:1.5;color:#334155"><tr>` +
        `<td style="border-left:3px solid ${brand};padding-left:12px">` +
        `<div style="font-weight:700;color:#0f172a;font-size:14px">${name}</div>` +
        `<div style="color:${brand};font-weight:600">${org}</div>` +
        `<div style="color:#64748b">${email}</div>` +
        `</td></tr></table>`,
    },
    {
      id: "minimal",
      label: "Minimal",
      html:
        `<div style="font-family:Georgia,serif;font-size:13px;color:#475569">` +
        `<span style="font-weight:600;color:#0f172a">${name}</span>&nbsp;|&nbsp;${org}` +
        `</div>`,
    },
  ];
}

