  const at = address.lastIndexOf("@");
  return at >= 0 ? address.slice(at + 1).toLowerCase() : "";
}

/** Format a stored Date as a `YYYY-MM-DD` string (or "" when null). */
function toDateInput(d: Date | null | undefined): string {
  if (!d) return "";
  try {
    return d.toISOString().slice(0, 10);
  } catch {
    return "";
  }
}

/** Parse a `YYYY-MM-DD` string into a UTC Date, or null when blank/invalid. */
function fromDateInput(s: string | null | undefined): Date | null {
  const v = (s ?? "").trim();
  if (!v) return null;
  const d = new Date(`${v}T00:00:00.000Z`);
  return Number.isNaN(d.getTime()) ? null : d;
}

