export async function saveMailboxSettings(
  input: { displayName?: string; signature?: string },
  mailboxAddress?: string,
): Promise<Result> {
  const { user, mailboxId } = await resolveMailbox(mailboxAddress);
  const limited = gate(`mail:settings:${user.id}`, 30, 60_000);
  if (limited) return limited;

  const displayName = (input.displayName ?? "").trim();
  const signature = input.signature ?? "";
  if (displayName.length > 120) return { ok: false, error: "Display name is too long (max 120 characters)." };
  if (signature.length > 5000) return { ok: false, error: "Signature is too long (max 5000 characters)." };

  await db.mailbox.update({
    where: { id: mailboxId },
    data: { displayName: displayName || null, signature: signature.trim() ? signature : null },
  });
  return { ok: true };
}

