/**
 * Save identity + signature onto the mailbox row. Only the fields actually
 * present in `input` are written, so the Identity and Signature sub-forms can
 * each save independently without clobbering the other's data.
 *
 * Signature HTML is sanitised server-side with `safeHtml` (defence in depth —
 * the client sanitises too) and a plain-text version is derived into the legacy
 * `signature` column so the text/plain MIME part always has a fallback.
 */
export async function saveMailboxSettings(
  input: {
    displayName?: string;
    replyTo?: string;
    organization?: string;
    signatureHtml?: string;
    signatureEnabled?: boolean;
    signatureOnReply?: boolean;
    signaturePlacement?: string;
  },
  mailboxAddress?: string,
): Promise<Result> {
  const { user, mailboxId } = await resolveMailbox(mailboxAddress);
  const limited = gate(`mail:settings:${user.id}`, 30, 60_000);
  if (limited) return limited;

  const data: {
    displayName?: string | null;
    replyTo?: string | null;
    organization?: string | null;
    signatureHtml?: string | null;
    signature?: string | null;
    signatureEnabled?: boolean;
    signatureOnReply?: boolean;
    signaturePlacement?: string;
  } = {};

  if (input.displayName !== undefined) {
    const displayName = input.displayName.trim();
    if (displayName.length > 120) return { ok: false, error: "Display name is too long (max 120 characters)." };
    data.displayName = displayName || null;
  }

  if (input.replyTo !== undefined) {
    const replyTo = input.replyTo.trim();
    if (replyTo && !EMAIL_RE.test(replyTo)) return { ok: false, error: "Reply-to must be a valid email address." };
    data.replyTo = replyTo || null;
  }

  if (input.organization !== undefined) {
    const organization = input.organization.trim();
    if (organization.length > 200) return { ok: false, error: "Organization is too long (max 200 characters)." };
    data.organization = organization || null;
  }

  if (input.signatureHtml !== undefined) {
    const clean = safeHtml(input.signatureHtml);
    if (clean.length > SIGNATURE_HTML_MAX) {
      return { ok: false, error: "Signature is too long. Please shorten it." };
    }
    data.signatureHtml = clean || null;
    const plain = signatureHtmlToText(clean);
    data.signature = plain ? plain : null;
  }

  if (input.signatureEnabled !== undefined) data.signatureEnabled = Boolean(input.signatureEnabled);
  if (input.signatureOnReply !== undefined) data.signatureOnReply = Boolean(input.signatureOnReply);
  if (input.signaturePlacement !== undefined) {
    data.signaturePlacement = input.signaturePlacement === "above" ? "above" : "below";
  }

  if (Object.keys(data).length > 0) {
    await db.mailbox.update({ where: { id: mailboxId }, data });
  }
  return { ok: true };
}

/**
 * Store a "forward a copy" rule on the mailbox row.
 *
 * NOTE: this is STORE-ONLY and honestly labelled as such in the UI. Mailcow has
 * no safe, mailbox-scoped forwarding primitive we can drive from the customer
 * panel without risking the account's real mail routing (an alias whose address
 * equals an existing mailbox is rejected by Mailcow, and editing SOGo sieve
 * filters is out of API scope), so we persist the preference and surface a
 * clear "stored, not yet auto-forwarding" note rather than pretend it forwards.
 */
export async function saveForwarding(
  input: { enabled: boolean; address?: string; keepCopy?: boolean },
  mailboxAddress?: string,
): Promise<Result> {
  const { user, mailboxId, address } = await resolveMailbox(mailboxAddress);
  const limited = gate(`mail:settings:${user.id}`, 30, 60_000);
  if (limited) return limited;

  const enabled = Boolean(input.enabled);
  const target = (input.address ?? "").trim().toLowerCase();
  const keepCopy = input.keepCopy !== false;

  if (enabled) {
    if (!target) return { ok: false, error: "Enter an address to forward to." };
    if (!EMAIL_RE.test(target)) return { ok: false, error: "That doesn't look like a valid email address." };
    if (target === address.toLowerCase()) return { ok: false, error: "Forwarding to this mailbox itself does nothing." };
  }

  await db.mailbox.update({
    where: { id: mailboxId },
    data: {
      forwardingAddress: enabled && target ? target : null,
      forwardKeepCopy: keepCopy,
    },
  });
  return { ok: true };
}

