"use client";

import { useCallback, useEffect, useRef, useState } from "react";
import {
  getMailboxSettings,
  saveMailboxSettings,
  saveAutoReply,
  saveForwarding,
  listAliases,
  addAlias,
  removeAlias,
  resetPassword,
  type MailboxSettings,
  type AliasRow,
} from "@/lib/actions-mailbox-settings";
import { safeHtml } from "@/lib/mail/render";
import {
  signatureHtmlToText,
  signatureTemplates,
  SIGNATURE_FONTS,
  SIGNATURE_SIZES,
  type SignaturePlacement,
} from "@/lib/mail/signature";
import { Icon } from "./util";

/** Mail server endpoints shown in the "configure your device" panel. */
const MAIL_HOST = "mail.nxeon.cloud";

type Section =
  | "identity"
  | "signature"
  | "autoreply"
  | "forwarding"
  | "storage"
  | "connection"
  | "aliases"
  | "password";

const SECTIONS: { key: Section; label: string; short: string; icon: keyof typeof Icon }[] = [
  { key: "identity", label: "Identity", short: "Identity", icon: "user" },
  { key: "signature", label: "Signature", short: "Signature", icon: "pen" },
  { key: "autoreply", label: "Auto-reply", short: "Auto-reply", icon: "reply" },
  { key: "forwarding", label: "Forwarding", short: "Forward", icon: "forward" },
  { key: "storage", label: "Storage", short: "Storage", icon: "hdd" },
  { key: "connection", label: "Connection", short: "Connect", icon: "mail" },
  { key: "aliases", label: "Aliases", short: "Aliases", icon: "tag" },
  { key: "password", label: "Change password", short: "Password", icon: "cog" },
];

export function MailSettings({
  mailboxAddress,
  storageUsedBytes,
  storageQuotaBytes,
  onClose,
  onSettingsChanged,
}: {
  mailboxAddress?: string;
  storageUsedBytes?: number;
  storageQuotaBytes?: number;
  onClose: () => void;
  /** Notify the parent so freshly-saved settings (signature/identity) apply to composing immediately. */
  onSettingsChanged?: () => void;
}) {
  const [section, setSection] = useState<Section>("signature");
  const [settings, setSettings] = useState<MailboxSettings | null>(null);
  const [loadError, setLoadError] = useState<string | null>(null);

  useEffect(() => {
    let alive = true;
    setSettings(null);
    setLoadError(null);
    getMailboxSettings(mailboxAddress)
      .then((s) => alive && setSettings(s))
      .catch((e) => alive && setLoadError(e instanceof Error ? e.message : "Couldn't load settings."));
    return () => {
      alive = false;
    };
  }, [mailboxAddress]);

  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") onClose();
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [onClose]);

  const patch = useCallback(
    (v: Partial<MailboxSettings>) => {
      setSettings((cur) => (cur ? { ...cur, ...v } : cur));
      onSettingsChanged?.();
    },
    [onSettingsChanged],
  );

  return (
    <div
      className="fixed inset-0 z-50 flex items-end justify-center bg-navy-950/70 p-0 backdrop-blur-sm sm:items-center sm:p-4"
      role="dialog"
      aria-modal="true"
      aria-label="Mailbox settings"
      onClick={onClose}
    >
      <div
        className="glass flex h-[92vh] w-full max-w-4xl flex-col overflow-hidden shadow-2xl animate-fade-up sm:h-[86vh]"
        onClick={(e) => e.stopPropagation()}
      >
        {/* Header */}
        <div className="flex items-center justify-between border-b border-white/[0.08] bg-white/[0.03] px-5 py-3">
          <div className="min-w-0">
            <h3 className="flex items-center gap-2 text-sm font-semibold text-white">
              <span className="text-brand-300"><Icon.cog size={16} /></span>
              Mailbox settings
            </h3>
            {settings && (
              <p className="mt-0.5 truncate text-xs text-slate-500" title={settings.address}>
                {settings.address}
              </p>
            )}
          </div>
          <button onClick={onClose} className="btn-ghost rounded-lg p-1.5" aria-label="Close">
            <Icon.close size={16} />
          </button>
        </div>

        <div className="flex min-h-0 flex-1 flex-col sm:flex-row">
          {/* Section nav */}
          <nav className="flex flex-none gap-1 overflow-x-auto border-b border-white/[0.06] p-2 sm:w-52 sm:flex-col sm:overflow-x-visible sm:overflow-y-auto sm:border-b-0 sm:border-r">
            {SECTIONS.map((s) => {
              const Ico = Icon[s.icon];
              const active = section === s.key;
              return (
                <button
                  key={s.key}
                  onClick={() => setSection(s.key)}
                  className={`flex flex-none items-center gap-2.5 whitespace-nowrap rounded-xl px-3 py-2 text-sm font-medium transition-colors ${
                    active ? "nav-item-active" : "text-slate-400 hover:bg-white/[0.05] hover:text-white"
                  }`}
                >
                  <Ico size={16} className={active ? "text-white" : ""} />
                  <span className="hidden sm:inline">{s.label}</span>
                  <span className="sm:hidden">{s.short}</span>
                </button>
              );
            })}
          </nav>

          {/* Section content */}
          <div className="min-h-0 flex-1 overflow-y-auto p-5">
            {loadError ? (
              <ErrorNote text={loadError} />
            ) : !settings ? (
              <LoadingRows />
            ) : section === "identity" ? (
              <IdentitySection mailboxAddress={mailboxAddress} initial={settings} onSaved={patch} />
            ) : section === "signature" ? (
              <SignatureSection mailboxAddress={mailboxAddress} initial={settings} onSaved={patch} />
            ) : section === "autoreply" ? (
              <AutoReplySection mailboxAddress={mailboxAddress} initial={settings} onSaved={patch} />
            ) : section === "forwarding" ? (
              <ForwardingSection mailboxAddress={mailboxAddress} initial={settings} onSaved={patch} />
            ) : section === "storage" ? (
              <StorageSection
                initial={settings}
                usedBytes={storageUsedBytes}
                quotaBytes={storageQuotaBytes}
              />
            ) : section === "connection" ? (
              <ConnectionSection address={settings.address} />
            ) : section === "aliases" ? (
              <AliasesSection mailboxAddress={mailboxAddress} domain={settings.domain} />
            ) : (
              <PasswordSection mailboxAddress={mailboxAddress} />
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

/* -------------------------------------------------------------------------- */
/* Section: Identity                                                           */
/* -------------------------------------------------------------------------- */

function IdentitySection({
  mailboxAddress,
  initial,
  onSaved,
}: {
  mailboxAddress?: string;
  initial: MailboxSettings;
  onSaved: (v: Partial<MailboxSettings>) => void;
}) {
  const [displayName, setDisplayName] = useState(initial.displayName);
  const [replyTo, setReplyTo] = useState(initial.replyTo);
  const [organization, setOrganization] = useState(initial.organization);
  const [saving, setSaving] = useState(false);
  const [msg, setMsg] = useState<string | null>(null);
  const [err, setErr] = useState<string | null>(null);

  async function save() {
    setSaving(true);
    setMsg(null);
    setErr(null);
    try {
      const res = await saveMailboxSettings({ displayName, replyTo, organization }, mailboxAddress);
      if (!res.ok) setErr(res.error || "Couldn't save.");
      else {
        setMsg("Saved.");
        onSaved({ displayName: displayName.trim(), replyTo: replyTo.trim(), organization: organization.trim() });
      }
    } catch (e) {
      setErr(e instanceof Error ? e.message : "Couldn't save.");
    } finally {
      setSaving(false);
    }
  }

  return (
    <div className="space-y-5">
      <SectionHead title="Identity" sub="How you appear to people you email from this mailbox." />

      <div>
        <label className="label" htmlFor="ms-name">Display name</label>
        <input
          id="ms-name"
          className="input"
          value={displayName}
          onChange={(e) => setDisplayName(e.target.value)}
          placeholder="e.g. Jane Doe"
          maxLength={120}
        />
        <p className="mt-1.5 text-xs text-slate-500">Shown as the sender name on messages you send.</p>
      </div>

      <div>
        <label className="label" htmlFor="ms-org">Organization</label>
        <input
          id="ms-org"
          className="input"
          value={organization}
          onChange={(e) => setOrganization(e.target.value)}
          placeholder="e.g. Acme Inc."
          maxLength={200}
        />
      </div>

      <div>
        <label className="label" htmlFor="ms-replyto">Reply-to address</label>
        <input
          id="ms-replyto"
          className="input"
          value={replyTo}
          onChange={(e) => setReplyTo(e.target.value)}
          placeholder="Leave blank to use your own address"
          maxLength={200}
          inputMode="email"
        />
        <p className="mt-1.5 text-xs text-slate-500">Replies are directed here instead of your sending address.</p>
      </div>

      <div>
        <label className="label">Sending address</label>
        <CopyField label="From" value={initial.address} mono />
      </div>

      <SaveRow saving={saving} msg={msg} err={err} onSave={save} />
    </div>
  );
}

/* -------------------------------------------------------------------------- */
/* Section: Signature (rich editor)                                            */
/* -------------------------------------------------------------------------- */

/** Escape plain text into HTML for the legacy-plain -> HTML seeding path. */
function plainToHtml(plain: string): string {
  const esc = plain.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
  return `<div style="font-family:-apple-system,Segoe UI,Roboto,sans-serif;font-size:13px;color:#334155">${esc.replace(/\n/g, "<br>")}</div>`;
}

function SignatureSection({
  mailboxAddress,
  initial,
  onSaved,
}: {
  mailboxAddress?: string;
  initial: MailboxSettings;
  onSaved: (v: Partial<MailboxSettings>) => void;
}) {
  const editorRef = useRef<HTMLDivElement | null>(null);
  const savedRange = useRef<Range | null>(null);

  const seedHtml =
    (initial.signatureHtml && safeHtml(initial.signatureHtml)) ||
    (initial.signature ? plainToHtml(initial.signature) : "");

  const [html, setHtml] = useState(seedHtml); // mirrors editor content, for preview + save
  const [enabled, setEnabled] = useState(initial.signatureEnabled);
  const [onReply, setOnReply] = useState(initial.signatureOnReply);
  const [placement, setPlacement] = useState<SignaturePlacement>(initial.signaturePlacement);
  const [saving, setSaving] = useState(false);
  const [msg, setMsg] = useState<string | null>(null);
  const [err, setErr] = useState<string | null>(null);

  // Seed the contentEditable once (React never re-writes it, so the caret is safe).
  useEffect(() => {
    if (editorRef.current) editorRef.current.innerHTML = seedHtml;
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const sync = useCallback(() => setHtml(editorRef.current?.innerHTML ?? ""), []);

  const saveSel = useCallback(() => {
    const sel = window.getSelection();
    if (sel && sel.rangeCount > 0) {
      const r = sel.getRangeAt(0);
      if (editorRef.current && editorRef.current.contains(r.commonAncestorContainer)) {
        savedRange.current = r.cloneRange();
      }
    }
  }, []);

  const restoreSel = useCallback(() => {
    const el = editorRef.current;
    if (!el) return;
    el.focus();
    const sel = window.getSelection();
    if (savedRange.current && sel) {
      try {
        sel.removeAllRanges();
        sel.addRange(savedRange.current);
      } catch {
        /* range detached — leave caret where it is */
      }
    }
  }, []);

  // Run an execCommand, degrading gracefully if the browser doesn't support it.
  const exec = useCallback(
    (cmd: string, value?: string) => {
      try {
        restoreSel();
        document.execCommand(cmd, false, value);
      } catch {
        /* unsupported command — ignore rather than crash the editor */
      }
      saveSel();
      sync();
    },
    [restoreSel, saveSel, sync],
  );

  const insertHtml = useCallback(
    (fragment: string) => {
      const el = editorRef.current;
      if (!el) return;
      restoreSel();
      let ok = false;
      try {
        ok = document.execCommand("insertHTML", false, fragment);
      } catch {
        ok = false;
      }
      if (!ok) el.innerHTML = el.innerHTML + fragment; // fallback: append
      saveSel();
      sync();
    },
    [restoreSel, saveSel, sync],
  );

  function promptLink() {
    const url = window.prompt("Link URL", "https://");
    if (!url) return;
    exec("createLink", url.trim());
  }

  function promptImage() {
    const url = window.prompt("Image URL (https://…)", "https://");
    if (!url) return;
    exec("insertImage", url.trim());
  }

  function clearFormatting() {
    exec("removeFormat");
    exec("unlink");
  }

  async function save() {
    setSaving(true);
    setMsg(null);
    setErr(null);
    try {
      const clean = safeHtml(editorRef.current?.innerHTML ?? "");
      const res = await saveMailboxSettings(
        { signatureHtml: clean, signatureEnabled: enabled, signatureOnReply: onReply, signaturePlacement: placement },
        mailboxAddress,
      );
      if (!res.ok) {
        setErr(res.error || "Couldn't save.");
      } else {
        setMsg("Saved.");
        setHtml(clean);
        onSaved({
          signatureHtml: clean,
          signature: signatureHtmlToText(clean),
          signatureEnabled: enabled,
          signatureOnReply: onReply,
          signaturePlacement: placement,
        });
      }
    } catch (e) {
      setErr(e instanceof Error ? e.message : "Couldn't save.");
    } finally {
      setSaving(false);
    }
  }

  const templates = signatureTemplates({
    name: initial.displayName,
    org: initial.organization,
    email: initial.address,
  });
  const previewHtml = safeHtml(html);

  return (
    <div className="space-y-5">
      <SectionHead
        title="Signature"
        sub="Design a rich signature that's added to messages you send. Formatting, links and images are supported."
      />

      <Toggle
        label={`Signature ${enabled ? "on" : "off"}`}
        checked={enabled}
        onChange={() => setEnabled((v) => !v)}
      />

      <div className={enabled ? "space-y-4" : "space-y-4 opacity-60"}>
        {/* Editor */}
        <div className="overflow-hidden rounded-xl border border-white/10">
          {/* Toolbar */}
          <div className="flex flex-wrap items-center gap-0.5 border-b border-white/10 bg-navy-900/90 px-2 py-1.5">
            <TBtn title="Bold" onClick={() => exec("bold")}>
              <span className="text-[15px] font-bold">B</span>
            </TBtn>
            <TBtn title="Italic" onClick={() => exec("italic")}>
              <span className="text-[15px] font-serif italic">I</span>
            </TBtn>
            <TBtn title="Underline" onClick={() => exec("underline")}>
              <span className="text-[15px] underline">U</span>
            </TBtn>
            <Sep />
            <select
              aria-label="Font"
              className="h-8 rounded-lg border border-white/10 bg-navy-800 px-1.5 text-xs text-slate-200 outline-none"
              defaultValue=""
              onChange={(e) => {
                if (e.target.value) exec("fontName", e.target.value);
                e.target.value = "";
              }}
            >
              <option value="" disabled>Font</option>
              {SIGNATURE_FONTS.map((f) => (
                <option key={f.label} value={f.css}>{f.label}</option>
              ))}
            </select>
            <select
              aria-label="Text size"
              className="h-8 rounded-lg border border-white/10 bg-navy-800 px-1.5 text-xs text-slate-200 outline-none"
              defaultValue=""
              onChange={(e) => {
                if (e.target.value) exec("fontSize", e.target.value);
                e.target.value = "";
              }}
            >
              <option value="" disabled>Size</option>
              {SIGNATURE_SIZES.map((s) => (
                <option key={s.value} value={s.value}>{s.label}</option>
              ))}
            </select>
            <label
              title="Text color"
              className="flex h-8 w-8 cursor-pointer items-center justify-center rounded-lg text-slate-300 hover:bg-white/10"
            >
              <span className="text-[13px] font-semibold">A</span>
              <span className="-mt-1 block h-1 w-3 rounded bg-brand-400" />
              <input
                type="color"
                className="absolute h-0 w-0 opacity-0"
                onChange={(e) => exec("foreColor", e.target.value)}
              />
            </label>
            <Sep />
            <TBtn title="Bulleted list" onClick={() => exec("insertUnorderedList")}>
              <ListIcon ordered={false} />
            </TBtn>
            <TBtn title="Numbered list" onClick={() => exec("insertOrderedList")}>
              <ListIcon ordered />
            </TBtn>
            <Sep />
            <TBtn title="Insert link" onClick={promptLink}>
              <LinkIcon />
            </TBtn>
            <TBtn title="Insert image by URL" onClick={promptImage}>
              <ImageIcon />
            </TBtn>
            <TBtn title="Horizontal rule" onClick={() => exec("insertHorizontalRule")}>
              <span className="text-base leading-none">—</span>
            </TBtn>
            <Sep />
            <TBtn title="Clear formatting" onClick={clearFormatting}>
              <ClearIcon />
            </TBtn>
          </div>

          {/* contentEditable — white surface so it matches what recipients see */}
          <div
            ref={editorRef}
            contentEditable
            suppressContentEditableWarning
            role="textbox"
            aria-multiline="true"
            aria-label="Signature editor"
            onInput={sync}
            onKeyUp={saveSel}
            onMouseUp={saveSel}
            onBlur={saveSel}
            className=" nx-sig-editor min-h-[10rem] max-h-[22rem] w-full overflow-auto bg-white px-4 py-3 text-sm leading-relaxed text-slate-900 outline-none"
          />
        </div>

        {/* Templates */}
        <div>
          <p className="section-label mb-2">Start from a template</p>
          <div className="flex flex-wrap gap-2">
            {templates.map((t) => (
              <button
                key={t.id}
                type="button"
                onClick={() => insertHtml(t.html)}
                className="btn-secondary px-3 py-1.5 text-xs"
              >
                {t.label}
              </button>
            ))}
          </div>
        </div>

        {/* Placement + reply toggles */}
        <Toggle
          label="Include on replies & forwards"
          checked={onReply}
          onChange={() => setOnReply((v) => !v)}
        />
        <div>
          <p className="section-label mb-2">Placement on replies</p>
          <Segmented
            value={placement}
            onChange={(v) => setPlacement(v as SignaturePlacement)}
            options={[
              { value: "below", label: "Below quoted text" },
              { value: "above", label: "Above quoted text" },
            ]}
          />
        </div>

        {/* Live preview — exactly the sanitized markup recipients receive */}
        <div>
          <p className="section-label mb-2">Preview (what recipients see)</p>
          <div className="overflow-hidden rounded-xl border border-white/10 bg-white p-4">
            {previewHtml ? (
              <div className="text-sm text-slate-900" dangerouslySetInnerHTML={{ __html: previewHtml }} />
            ) : (
              <p className="text-sm text-slate-400">Your signature preview will appear here.</p>
            )}
          </div>
          <p className="mt-1.5 text-xs text-slate-500">
            Scripts, event handlers and unsafe URLs are stripped automatically. Images must use an https:// URL
            (inline data images are removed for safety).
          </p>
        </div>
      </div>

      <SaveRow saving={saving} msg={msg} err={err} onSave={save} />
    </div>
  );
}

