function AutoReplySection({
  mailboxAddress,
  initial,
  onSaved,
}: {
  mailboxAddress?: string;
  initial: MailboxSettings;
  onSaved: (v: Partial<MailboxSettings>) => void;
}) {
  const [enabled, setEnabled] = useState(initial.autoReplyEnabled);
  const [subject, setSubject] = useState(initial.autoReplySubject);
  const [body, setBody] = useState(initial.autoReplyBody);
  const [start, setStart] = useState(initial.autoReplyStart);
  const [end, setEnd] = useState(initial.autoReplyEnd);
  const [saving, setSaving] = useState(false);
  const [msg, setMsg] = useState<string | null>(null);
  const [err, setErr] = useState<string | null>(null);

  async function save() {
    setSaving(true);
    setMsg(null);
    setErr(null);
    try {
      const res = await saveAutoReply({ enabled, subject, body, start, end }, mailboxAddress);
      if (!res.ok) setErr(res.error || "Couldn't save.");
      else {
        setMsg("Saved.");
        onSaved({
          autoReplyEnabled: enabled,
          autoReplySubject: subject.trim(),
          autoReplyBody: body.trim(),
          autoReplyStart: start,
          autoReplyEnd: end,
        });
      }
    } catch (e) {
      setErr(e instanceof Error ? e.message : "Couldn't save.");
    } finally {
      setSaving(false);
    }
  }

  return (
    <div className="space-y-5">
      <SectionHead title="Auto-reply" sub="Send an automatic response to incoming messages while you're away." />

      <Toggle label={`Auto-reply ${enabled ? "on" : "off"}`} checked={enabled} onChange={() => setEnabled((v) => !v)} />

      <div className={enabled ? "space-y-4" : "space-y-4 opacity-50"}>
        <div>
          <label className="label" htmlFor="ar-subject">Subject</label>
          <input
            id="ar-subject"
            className="input"
            value={subject}
            onChange={(e) => setSubject(e.target.value)}
            placeholder="Out of office"
            maxLength={200}
            disabled={!enabled}
          />
        </div>
        <div>
          <label className="label" htmlFor="ar-body">Message</label>
          <textarea
            id="ar-body"
            className="input min-h-[8rem] resize-y leading-relaxed"
            value={body}
            onChange={(e) => setBody(e.target.value)}
            placeholder="Thanks for your email. I'm away until…"
            maxLength={5000}
            disabled={!enabled}
          />
        </div>
        <div className="grid gap-3 sm:grid-cols-2">
          <div>
            <label className="label" htmlFor="ar-start">Only send from</label>
            <input
              id="ar-start"
              type="date"
              className="input"
              value={start}
              onChange={(e) => setStart(e.target.value)}
              disabled={!enabled}
            />
          </div>
          <div>
            <label className="label" htmlFor="ar-end">Until</label>
            <input
              id="ar-end"
              type="date"
              className="input"
              value={end}
              onChange={(e) => setEnd(e.target.value)}
              disabled={!enabled}
            />
          </div>
        </div>
        <p className="text-xs text-slate-500">Leave the dates blank to keep the auto-reply active with no end date.</p>
      </div>

      <div className="rounded-xl border border-amber-400/20 bg-amber-400/[0.06] px-4 py-3 text-xs text-amber-200/90">
        Auto-reply is saved to your mailbox. Server-side delivery of auto-replies is rolling out — until then,
        these settings are stored but not yet sent automatically.
      </div>

      <SaveRow saving={saving} msg={msg} err={err} onSave={save} />
    </div>
  );
}

