function fmtBytes(n: number): string {
  if (!Number.isFinite(n) || n <= 0) return "0 MB";
  const units = ["B", "KB", "MB", "GB", "TB"];
  let v = n;
  let i = 0;
  while (v >= 1024 && i < units.length - 1) {
    v /= 1024;
    i++;
  }
  return `${v >= 10 || i === 0 ? Math.round(v) : v.toFixed(1)} ${units[i]}`;
}

function StorageSection({
  initial,
  usedBytes,
  quotaBytes,
}: {
  initial: MailboxSettings;
  usedBytes?: number;
  quotaBytes?: number;
}) {
  const quota =
    quotaBytes && quotaBytes > 0
      ? quotaBytes
      : initial.quotaMB
        ? initial.quotaMB * 1024 * 1024
        : 0;
  const used = usedBytes && usedBytes > 0 ? usedBytes : 0;
  const haveUsage = usedBytes !== undefined;
  const pct = quota > 0 ? Math.min(100, Math.round((used / quota) * 100)) : 0;
  const nearFull = pct >= 90;

  return (
    <div className="space-y-5">
      <SectionHead title="Storage" sub="How much of this mailbox's quota is in use." />

      <div className="rounded-2xl border border-white/[0.08] bg-white/[0.02] p-5">
        <div className="flex items-baseline justify-between">
          <span className="text-2xl font-semibold text-white">{fmtBytes(used)}</span>
          <span className="text-sm text-slate-400">of {quota > 0 ? fmtBytes(quota) : "—"}</span>
        </div>

        <div className="mt-3 h-2.5 w-full overflow-hidden rounded-full bg-white/10">
          <div
            className={`h-full rounded-full ${nearFull ? "bg-gradient-to-r from-amber-400 to-red-400" : "bg-gradient-to-r from-accent-blue to-brand-500"}`}
            style={{ width: `${quota > 0 ? pct : 0}%` }}
          />
        </div>

        <p className="mt-2 text-xs text-slate-500">
          {quota > 0 ? `${pct}% used` : "Quota not set"}
          {!haveUsage && " — live usage is unavailable right now; showing your plan quota."}
          {nearFull && haveUsage && " — you're running low. Clear out large messages or upgrade your plan."}
        </p>
      </div>
    </div>
  );
}

