/* Section: Aliases                                                            */
/* -------------------------------------------------------------------------- */

function AliasesSection({ mailboxAddress, domain }: { mailboxAddress?: string; domain: string }) {
  const [aliases, setAliases] = useState<AliasRow[] | null>(null);
  const [loadErr, setLoadErr] = useState<string | null>(null);
  const [newAlias, setNewAlias] = useState("");
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState<string | null>(null);

  const load = useCallback(async () => {
    setLoadErr(null);
    try {
      const res = await listAliases(mailboxAddress);
      if (!res.ok) {
        setLoadErr(res.error || "Couldn't load aliases.");
        setAliases([]);
      } else {
        setAliases(res.aliases);
      }
    } catch (e) {
      setLoadErr(e instanceof Error ? e.message : "Couldn't load aliases.");
      setAliases([]);
    }
  }, [mailboxAddress]);

  useEffect(() => {
    void load();
  }, [load]);

  async function add() {
    const val = newAlias.trim();
    if (!val) return;
    setBusy(true);
    setErr(null);
    try {
      const res = await addAlias(val, undefined, mailboxAddress);
      if (!res.ok) setErr(res.error || "Couldn't add alias.");
      else {
        setNewAlias("");
        await load();
      }
    } catch (e) {
      setErr(e instanceof Error ? e.message : "Couldn't add alias.");
    } finally {
      setBusy(false);
    }
  }

  async function remove(id: number) {
    setErr(null);
    // Optimistic removal.
    setAliases((cur) => (cur ? cur.filter((a) => a.id !== id) : cur));
    try {
      const res = await removeAlias(id, mailboxAddress);
      if (!res.ok) {
        setErr(res.error || "Couldn't remove alias.");
        await load();
      }
    } catch (e) {
      setErr(e instanceof Error ? e.message : "Couldn't remove alias.");
      await load();
    }
  }

  return (
    <div className="space-y-5">
      <SectionHead
        title="Aliases"
        sub={`Extra addresses on ${domain || "your domain"} that deliver to this mailbox.`}
      />

      {/* Add form */}
      <div className="flex flex-col gap-2 sm:flex-row">
        <div className="flex flex-1 items-stretch overflow-hidden rounded-xl border border-white/10 bg-navy-900/80 focus-within:border-brand-400/60 focus-within:ring-2 focus-within:ring-brand-500/20">
          <input
            className="min-w-0 flex-1 bg-transparent px-3.5 py-2.5 text-sm text-slate-100 outline-none placeholder:text-slate-500"
            value={newAlias}
            onChange={(e) => setNewAlias(e.target.value)}
            onKeyDown={(e) => {
              if (e.key === "Enter") void add();
            }}
            placeholder="sales"
            aria-label="New alias"
          />
          {!newAlias.includes("@") && domain && (
            <span className="flex flex-none items-center pr-3 text-sm text-slate-500">@{domain}</span>
          )}
        </div>
        <button className="btn-primary flex-none" onClick={add} disabled={busy || !newAlias.trim()}>
          {busy ? "Adding…" : "Add alias"}
        </button>
      </div>
      {err && <ErrorNote text={err} />}

      {/* List */}
      {aliases === null ? (
        <LoadingRows rows={3} />
      ) : loadErr ? (
        <ErrorNote text={loadErr} />
      ) : aliases.length === 0 ? (
        <EmptyNote text="No aliases yet. Add one above to start forwarding another address into this mailbox." />
      ) : (
        <ul className="divide-y divide-white/[0.06] overflow-hidden rounded-xl border border-white/[0.06]">
          {aliases.map((a) => (
            <li key={a.id} className="flex items-center gap-3 px-4 py-2.5">
              <span className="text-brand-300"><Icon.tag size={15} /></span>
              <div className="min-w-0 flex-1">
                <p className="truncate font-mono text-sm text-slate-100">{a.address}</p>
                <p className="truncate text-xs text-slate-500">→ {a.goto || "—"}</p>
              </div>
              {!a.active && <span className="flex-none text-[11px] text-amber-300">inactive</span>}
              <button
                onClick={() => remove(a.id)}
                className="btn-ghost flex-none rounded-lg p-1.5 text-slate-500 hover:text-red-300"
                aria-label={`Remove alias ${a.address}`}
                title="Remove alias"
              >
                <Icon.trash size={15} />
              </button>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

