function PasswordSection({ mailboxAddress }: { mailboxAddress?: string }) {
  const [busy, setBusy] = useState(false);
  const [password, setPassword] = useState<string | null>(null);
  const [err, setErr] = useState<string | null>(null);

  async function reset() {
    if (!confirm("Reset this mailbox's password? The current password will stop working everywhere.")) return;
    setBusy(true);
    setErr(null);
    setPassword(null);
    try {
      const res = await resetPassword(mailboxAddress);
      if (res.error) setErr(res.error);
      else if (res.password) setPassword(res.password);
    } catch (e) {
      setErr(e instanceof Error ? e.message : "Couldn't reset the password.");
    } finally {
      setBusy(false);
    }
  }

  return (
    <div className="space-y-5">
      <SectionHead
        title="Change password"
        sub="Generate a new password for this mailbox. It applies to webmail and any connected mail apps."
      />

      {password ? (
        <div className="space-y-3">
          <div className="rounded-xl border border-emerald-400/20 bg-emerald-400/[0.06] px-4 py-3 text-xs text-emerald-200/90">
            New password set. Copy it now — it won't be shown again.
          </div>
          <CopyField label="New password" value={password} mono />
        </div>
      ) : (
        <p className="text-sm text-slate-400">
          A strong password is generated and applied on the mail server, then shown once here for you to
          copy into your other mail apps.
        </p>
      )}

      {err && <ErrorNote text={err} />}

      <button className="btn-secondary" onClick={reset} disabled={busy}>
        {busy ? "Resetting…" : password ? "Reset again" : "Reset password"}
      </button>
    </div>
  );
}

