function CopyField({
  label,
  value,
  copyable = true,
  mono = false,
}: {
  label: string;
  value: string;
  copyable?: boolean;
  mono?: boolean;
}) {
  const [copied, setCopied] = useState(false);
  const copy = useCallback(async () => {
    try {
      await navigator.clipboard.writeText(value);
      setCopied(true);
      setTimeout(() => setCopied(false), 1400);
    } catch {
      /* clipboard blocked — no-op */
    }
  }, [value]);

  return (
    <div className="flex items-center gap-2 rounded-xl border border-white/[0.08] bg-navy-900/60 px-3 py-2">
      <div className="min-w-0 flex-1">
        <p className="text-[10px] font-semibold uppercase tracking-wide text-slate-500">{label}</p>
        <p className={`truncate text-sm text-slate-100 ${mono ? "font-mono" : ""}`} title={value}>
          {value}
        </p>
      </div>
      {copyable && (
        <button
          onClick={copy}
          className="btn-ghost flex-none rounded-lg p-1.5 text-slate-400 hover:text-white"
          aria-label={`Copy ${label}`}
          title={copied ? "Copied" : "Copy"}
        >
          {copied ? <CheckIcon /> : <ClipboardIcon />}
        </button>
      )}
    </div>
  );
}

