const esc = (s: string) => s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
// Compose the outgoing body. User text becomes both the text part and,
// combined with any quoted original, a simple HTML part.
const escaped = esc(body);
// For replies/forwards the signature is appended BELOW the quoted original
// (plain text, treated as text for safety). New messages already carry the
// signature inline in `body`, so no separate block is added there.
const sig = draft.signature?.trim();
const sigText = sig ? `\n\n-- \n${sig}` : "";
const sigHtml = sig
  ? `<br><div style="white-space:pre-wrap;font-family:-apple-system,Segoe UI,Roboto,sans-serif;font-size:13px;line-height:1.6;color:#64748b">-- <br>${esc(sig)}</div>`
  : "";
const htmlBody =
  `<div style="white-space:pre-wrap;font-family:-apple-system,Segoe UI,Roboto,sans-serif;font-size:14px;line-height:1.6;color:#1e293b">${escaped}</div>` +
  (draft.quotedHtml
    ? `<br><blockquote style="margin:0 0 0 12px;padding-left:12px;border-left:3px solid #e2e8f0;color:#64748b">${draft.quotedHtml}</blockquote>`
    : "") +
  sigHtml;

await onSend({
  to: to.trim(),
  cc: cc.trim() || undefined,
  subject: subject.trim() || "(no subject)",
  text: body + sigText,
  html: htmlBody,
